/* eslint-disable no-restricted-globals */
/**
 * Firebase Cloud Messaging Service Worker.
 *
 * Handles incoming push messages when the app is in the background (tab closed
 * or minimized). Foreground messages are handled by the onMessage() callback
 * in AppContext.
 *
 * This file lives in /public so Vite copies it to the build root unchanged.
 * The Workbox service worker (generated by vite-plugin-pwa) imports this via
 * importScripts in the PWA manifest config.
 */

// Firebase SDK needs these imported for background message handling.
importScripts('https://www.gstatic.com/firebasejs/12.17.1/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/12.17.1/firebase-messaging-compat.js');

// Initialize Firebase in the service worker.
// These values come from the Firebase project console — they are public (not secret).
firebase.initializeApp({
  apiKey: 'AIzaSyC-0D4K-Rzq3jdWjkduWCihlD1rSb_BqQI',
  authDomain: 'track-tracker-ca74a.firebaseapp.com',
  projectId: 'track-tracker-ca74a',
  messagingSenderId: '659715394517',
  appId: '1:659715394517:web:5e02f9a2e7541f92a68b5c',
});

const messaging = firebase.messaging();

// Background push handler — shows a system notification.
messaging.onBackgroundMessage((payload) => {
  const title = payload.notification?.title || 'عملية بيع جديدة';
  const body = payload.notification?.body || 'سجّل سائق عملية بيع جديدة';
  const icon = payload.notification?.icon || '/icons/icon-192.png';

  self.registration.showNotification(title, {
    body,
    icon,
    tag: `sale-${Date.now()}`,
    data: payload.data,
  });
});

// Handle notification click — focus or open the app.
self.addEventListener('notificationclick', (event) => {
  event.notification.close();

  const urlToOpen = new URL('/', self.location.origin).href;

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      // If a window client is already open, focus it.
      for (const client of clientList) {
        if (client.url.startsWith(self.location.origin) && 'focus' in client) {
          return client.focus();
        }
      }
      // Otherwise open a new window.
      return self.clients.openWindow(urlToOpen);
    })
  );
});
